    if first_arg and isinstance(first_arg, str):
        if first_arg.startswith(("./", "/", "../")):
            return

    return bandit.Issue(
        severity=bandit.MEDIUM,
        confidence=bandit.HIGH,
        text=(
            f"Unsafe Hugging Face Hub download without revision pinning "
            f"in {func_name}()"
